css:
.mt{display:inline}@media (prefers-reduced-motion:reduce){.mt{display:none} }
.nm{display:none}@media (prefers-reduced-motion:reduce){.nm{display:inline} }
.tw1{animation:tw 3.1s ease-in-out infinite}.tw2{animation:tw 4.3s ease-in-out infinite}.tw3{animation:tw 5.7s ease-in-out infinite}@keyframes tw{50%{opacity:.25} }
.fk{transform-box:fill-box;transform-origin:50% 100%;animation:fk .35s ease-in-out infinite alternate}@keyframes fk{to{transform:scale(.82,1.22);opacity:.75} }
.fg{transform-box:fill-box;transform-origin:left;animation:wvf 1.1s ease-in-out infinite alternate}@keyframes wvf{from{transform:skewY(-9deg) scaleX(1)}to{transform:skewY(9deg) scaleX(.88)} }
.fgs{transform-box:fill-box;transform-origin:left;animation:wvs 1.6s ease-in-out infinite alternate}@keyframes wvs{from{transform:skewY(-3deg)}to{transform:skewY(3deg) scaleX(.96)} }
.rock{transform-box:fill-box;transform-origin:center;animation:rock 6s ease-in-out infinite}@keyframes rock{0%,78%,100%{transform:rotate(0) scale(1)}84%{transform:rotate(14deg) scale(1.08)}90%{transform:rotate(-7deg) scale(1.02)}95%{transform:rotate(2deg)} }
.bob{transform-box:fill-box;transform-origin:center;animation:bob 5s ease-in-out infinite}@keyframes bob{50%{transform:translateY(-14px) rotate(3deg)} }
.bob2{transform-box:fill-box;transform-origin:center;animation:bob2 3s ease-in-out infinite}@keyframes bob2{50%{transform:translateY(-6px) rotate(-4deg)} }
.rc{animation:rec 6s ease-out infinite}@keyframes rec{0%,9%,100%{transform:translateX(0)}1.5%{transform:translateX(-10px)} }
.mf,.sm{transform-box:fill-box;transform-origin:center;opacity:0}.mf{animation:mfl 6s ease-out infinite}.sm{animation:smk 6s ease-out infinite}
@keyframes mfl{0%{opacity:0;transform:scale(.2)}1%{opacity:1;transform:scale(1.1)}4%,100%{opacity:0;transform:scale(1.5)} }
@keyframes smk{0%{opacity:0;transform:translate(0,0) scale(.3)}2%{opacity:.8}20%,100%{opacity:0;transform:translate(34px,-34px) scale(2.1)} }
.up{animation:up 11s cubic-bezier(.22,.8,.24,1) infinite both}@keyframes up{0%{transform:translateY(270px)}9%,90%{transform:translateY(0)}96%,100%{transform:translateY(270px)} }
.flap{transform-box:fill-box;transform-origin:50% 100%;animation:flap .5s ease-in-out infinite alternate}@keyframes flap{from{transform:scaleY(1)}to{transform:scaleY(-.55)} }
.pls{animation:pls 2.4s ease-in-out infinite}@keyframes pls{50%{opacity:.4} }
.dash{animation:dash 1.6s linear infinite}@keyframes dash{to{stroke-dashoffset:-26} }
@media (prefers-reduced-motion:reduce){svg *{animation:none!important} }
